var t=`0809-ifisashi`;var n=`world-0809`;var s=`ZM`;var a=`eastern-africa`;var o=4;var r=29;var l={en:`Ifisashi`,ua:`Іфісаші`};var d={en:`Ifisashi is a Zambia dish made with yellow onion, tomato, spinach, peanut butter. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Іфісаші, страва кухні країни Замбія. Основні складники: жовта цибуля, помідор, шпинат, арахісова паста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var m=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,150,`g`],[`tomato`,230,`g`],[`canola-oil`,32,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 12 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 12 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:12,i:[[`spinach`,450,`g`],[`water`,180,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`peanut-butter`,145,`g`],[`coconut-milk`,150,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`crushed-red-pepper`,2,`g`]]}];var g={slug:t,id:n,country:`ZM`,region:a,servings:4,minutes:29,title:l,text:d,steps:m};export{s as country,g as default,n as id,r as minutes,a as region,o as servings,t as slug,m as steps,d as text,l as title};